19		import { formatCurrency } from '$lib/utils/formatCurrency';
20		import {
21			buildSpendingReport,
22			type SpendingReport,
23			type SpendingCategory,
24			type Cell,
25			type ReportRow
26		} from '$lib/utils/spendingReport';
27		import {
28			buildSpendingDrilldownParams,
