34		import type { Session } from '@supabase/supabase-js';
35	
36		let session: Session | null = $state(null);
37		let familyId: string | null = $state(null);
38		let year = $state(new Date().getFullYear());
39		let view = $state<'table' | 'chart'>('table');
40		let loading = $state(true);
41		let error: string | null = $state(null);
42		let report = $state<SpendingReport | null>(null);
43		// Kept in state (not just local to loadReport) so cell drill-down can expand a
44		// Grouping/Importance to its member category ids.
45		let categories = $state<SpendingCategory[]>([]);
46		let groups = $state<CategoryGroup[]>([]);
47	
48		onMount(async () => {
49			const { data } = await supabase.auth.getSession();
50			session = data.session;
51			if (!session) return;
52	
53			familyId = await getDefaultFamilyId();
54			if (!familyId) {
55				error = 'No family found. Please contact support.';
56				loading = false;
57				return;
58			}
59	
60			await loadReport();
61		});
62	
63		async function loadReport() {
64			if (!session?.user || !familyId) return;
65	
66			try {
67				loading = true;
68				error = null;
69	
70				const categoryService = new CategoryService(supabase);
71				const expenseService = new ExpenseService(supabase);
72	
73				// Seed the default hierarchy the first time a family opens the report
74				// (idempotent server-side), mirroring how categories self-initialize.
75				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
76				if (importanceAreas.length === 0) {
77					await categoryService.createDefaultHierarchy(familyId);
78					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
79				}
80	
81				const [loadedGroups, loadedCategories, expenses] = await Promise.all([
82					categoryService.getFamilyGroups(familyId),
83					categoryService.getFamilyCategories(familyId),
84					expenseService.getExpenses(session.user.id, {
85						startDate: `${year}-01-01`,
86						endDate: `${year}-12-31`
87					})
88				]);
89	
90				groups = loadedGroups;
91				categories = loadedCategories;
92				report = buildSpendingReport(expenses, loadedCategories, loadedGroups, importanceAreas, year);
93			} catch (err) {
94				console.error('Error loading spending report:', err);
95				error = err instanceof Error ? err.message : 'Failed to load the spending report';
96			} finally {
97				loading = false;
98			}
99		}
100	
101		function changeYear(delta: number) {
102			year += delta;
103			loadReport();
104		}
105	
106		/** A cell renders blank when no receipts fell in it, otherwise the amount. */
107		function cellText(cell: Cell): string {
108			return cell.count === 0 ? '' : formatCurrency(cell.amount);
109		}
110	
111		/**
112		 * The drill-down scope for a detail row: a real category when the row maps to
113		 * one (including a named-but-ungrouped Uncategorized row), otherwise the
114		 * "(No category)" catch-all drills to the uncategorized Expenses filter.
115		 */
116		function rowScope(row: ReportRow): DrilldownScope {
117			return row.categoryId
118				? { kind: 'category', categoryId: row.categoryId }
119				: { kind: 'uncategorized' };
120		}
121	
122		/**
123		 * The Expenses-view query a clicked cell links to, filtered to exactly what it
124		 * sums. Returns just the query string; the template builds the `/expenses?…`
125		 * template literal and wraps it in `resolve()` (both SvelteKit's typed `resolve`
126		 * and the no-navigation-without-resolve lint rule want that at the call site).
127		 */
128		function drilldownQuery(scope: DrilldownScope, column: DrilldownColumn): string {
129			return buildSpendingDrilldownParams(scope, column, year, categories, groups).toString();
130		}
131	
132		const hasData = $derived(report !== null && report.months.length > 0);
133	</script>
